<?php
declare(strict_types=1);
require_once __DIR__ . '/funcoes.php';
$titulo='Estoque';
$erro=null;
try {
    $modo = (string)($_GET['modo'] ?? 'baixo');
    if (!in_array($modo,['baixo','todos'],true)) $modo='baixo';
    $cond = $modo==='baixo' ? 'AND sp.saldo_disponivel<p.estoque_minimo' : '';
    $produtos = queryAll("SELECT p.id_produto,p.codigo_interno,p.nome,s.nome setor,p.tipo_venda,p.estoque_minimo,sp.saldo_lotes,sp.perdas_pendentes,sp.saldo_disponivel,CASE WHEN EXISTS(SELECT 1 FROM ITEM_PEDIDO_COMPRA ip JOIN PEDIDO_COMPRA pc ON pc.id_pedido=ip.id_pedido WHERE ip.id_produto=p.id_produto AND pc.status IN ('aberto','parcial')) THEN 'sim' ELSE 'nao' END pedido_em_aberto FROM PRODUTO p JOIN SETOR s ON s.id_setor=p.id_setor JOIN vw_saldo_produto sp ON sp.id_produto=p.id_produto WHERE p.ativo=1 $cond ORDER BY (sp.saldo_disponivel<p.estoque_minimo) DESC,sp.saldo_disponivel,p.nome");
    $resumo = queryOne("SELECT COUNT(*) produtos_ativos,SUM(sp.saldo_disponivel<p.estoque_minimo) abaixo FROM PRODUTO p JOIN vw_saldo_produto sp ON sp.id_produto=p.id_produto WHERE p.ativo=1");
    $idProduto=filter_input(INPUT_GET,'produto',FILTER_VALIDATE_INT); $lotes=[]; $produtoSel=null;
    if($idProduto){$produtoSel=queryOne("SELECT p.id_produto,p.nome,p.codigo_interno,s.nome setor,p.estoque_minimo,sp.saldo_disponivel FROM PRODUTO p JOIN SETOR s ON s.id_setor=p.id_setor JOIN vw_saldo_produto sp ON sp.id_produto=p.id_produto WHERE p.id_produto=:id",['id'=>$idProduto]);$lotes=queryAll("SELECT id_lote,codigo_lote,data_fabricacao,data_validade,quantidade_recebida,quantidade_atual,custo_unitario FROM LOTE WHERE id_produto=:id ORDER BY data_validade IS NULL,data_validade",['id'=>$idProduto]);}
} catch(Throwable $e){$erro=$e->getMessage();$produtos=$lotes=[];$resumo=[];$produtoSel=null;}
require __DIR__.'/partials/header.php';
?>
<?php if($erro): ?><div class="notice notice-danger"><?= e($erro) ?></div><?php endif; ?>
<section class="cards"><div class="card metric"><div class="label">Produtos ativos</div><div class="value"><?= e($resumo['produtos_ativos']??0) ?></div><div class="hint">Cadastro PRODUTO</div></div><div class="card metric"><div class="label">Abaixo do mínimo</div><div class="value"><?= e($resumo['abaixo']??0) ?></div><div class="hint">Mesma condição da G07</div></div></section>
<section class="panel"><div class="panel-head"><h2>Saldo por produto</h2><div><a class="btn <?= $modo==='baixo'?'btn-primary':'btn-secondary' ?>" href="estoque.php?modo=baixo">Só abaixo do mínimo</a> <a class="btn <?= $modo==='todos'?'btn-primary':'btn-secondary' ?>" href="estoque.php?modo=todos">Todos</a></div></div><div class="notice notice-info">O saldo exibido vem da view <strong>vw_saldo_produto</strong>: saldo dos lotes menos perdas pendentes.</div><div class="table-wrap"><table><thead><tr><th>Código</th><th>Produto</th><th>Setor</th><th>Tipo</th><th>Saldo lotes</th><th>Perdas pendentes</th><th>Disponível</th><th>Mínimo</th><th>Pedido aberto</th><th></th></tr></thead><tbody><?php if(!$produtos): ?><tr><td colspan="10" class="empty">Nenhum produto para o filtro.</td></tr><?php endif; ?><?php foreach($produtos as $r): $baixo=(float)$r['saldo_disponivel']<(float)$r['estoque_minimo']; ?><tr><td><?= e($r['codigo_interno']) ?></td><td><?= e($r['nome']) ?></td><td><?= e($r['setor']) ?></td><td><?= e($r['tipo_venda']) ?></td><td><?= e(numero($r['saldo_lotes'])) ?></td><td><?= e(numero($r['perdas_pendentes'])) ?></td><td class="<?= $baixo?'status-low':'status-ok' ?>"><?= e(numero($r['saldo_disponivel'])) ?></td><td><?= e(numero($r['estoque_minimo'])) ?></td><td><span class="badge <?= $r['pedido_em_aberto']==='sim'?'badge-ok':'badge-neutral' ?>"><?= e($r['pedido_em_aberto']) ?></span></td><td><a class="btn btn-secondary" href="estoque.php?modo=<?= e($modo) ?>&produto=<?= e($r['id_produto']) ?>">Lotes</a></td></tr><?php endforeach; ?></tbody></table></div></section>
<?php if($produtoSel): ?><section class="panel"><div class="panel-head"><h2>Lotes — <?= e($produtoSel['nome']) ?></h2><a class="btn btn-secondary" href="estoque.php?modo=<?= e($modo) ?>">Fechar</a></div><div class="kpi-line"><span class="badge badge-neutral">Código <?= e($produtoSel['codigo_interno']) ?></span><span class="badge badge-neutral">Setor <?= e($produtoSel['setor']) ?></span><span class="badge badge-neutral">Saldo <?= e(numero($produtoSel['saldo_disponivel'])) ?></span><span class="badge badge-neutral">Mínimo <?= e(numero($produtoSel['estoque_minimo'])) ?></span></div><br><div class="table-wrap"><table><thead><tr><th>Lote</th><th>Fabricação</th><th>Validade</th><th>Recebida</th><th>Atual</th><th>Custo</th></tr></thead><tbody><?php foreach($lotes as $r): ?><tr><td><?= e($r['codigo_lote']?:'#'.$r['id_lote']) ?></td><td><?= e(dataBr($r['data_fabricacao'])) ?></td><td><?= e(dataBr($r['data_validade'])) ?></td><td><?= e(numero($r['quantidade_recebida'])) ?></td><td><?= e(numero($r['quantidade_atual'])) ?></td><td><?= e(brl($r['custo_unitario'])) ?></td></tr><?php endforeach; ?></tbody></table></div></section><?php endif; ?>
<?php require __DIR__.'/partials/footer.php'; ?>
